    sub_token = auth_vault.mint_single_use_token(agent_id, proposed_action, ttl=60)
    // 3. For irreversible operations, force execution into a canary audience
    canary_target = audience.sample_isolated_slice(proposed_action.target, ratio=0.01)
    dry_run = martech_adapter.apply(sub_token, proposed_action, target=canary_target)
    // 4. Verification window: observe unsubscribe or spend spikes before release
    if telemetry.detects_abnormal_variance(dry_run, window_minutes=15):
        return martech_adapter.quarantine_and_revoke(sub_token, dry_run)
    // 5. Replace synchronous rubber stamps with progressive rate-limited rollout
    return martech_adapter.schedule_gradual_rollout(dry_run, pace="10pct_per_hour")

